  const before=`reports ${(shiftReports.reports||[]).length}, intake ${(shiftReports.issues||[]).length}, intel intake ${(shiftIntel.intake||[]).length}, intel issues ${(shiftIntel.issues||[]).length}, reference ${(shiftIntel.reference||[]).length}`;
