  shiftIntel.audit=Array.isArray(shiftIntel.audit)?shiftIntel.audit:[];
  const maxIssue=shiftIntel.issues.reduce((m,x)=>Math.max(m,Number(x.id)||0),0),maxItem=shiftIntel.intake.reduce((m,x)=>Math.max(m,Number(x.id)||0),0);
