function siNoise(t){return typeof isShiftReportNoiseText==='function'?isShiftReportNoiseText(t):!String(t||'').trim()}
function siWords(t){return String(t||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(w=>w.length>2&&!['the','and','for','with','that','this','from','none','note','shift','officer','security'].includes(w))}
function siLocation(t){const x=String(t||'').toLowerCase();const locs=['gate','base','reception','crosswalk','grocery','produce','freezer','dock','warehouse','back wall','parking','turnstile','hba','patrol','camera','door'];return locs.find(l=>x.includes(l))||''}
function siCategory(raw){if(raw.category)return raw.category;const t=String(raw.type||raw.title||raw.detail||'').toLowerCase();if(/alarm|jockey|pump|tamper|panel|smoke|detector/.test(t))return 'Alarm / Fire System';if(/back\s*log|backlog|trailer|dock|temperature/.test(t))return 'Logistics / Trailer Monitoring';if(/leak|rain|water|weather|lightning|facility|wall|door|damage/.test(t))return 'Facility / Safety';if(/off[-\s]?duty|police|bpd|off duty/.test(t))return 'Off-Duty Officer';if(/patrol|safety|hazard|round/.test(t))return 'Patrol / Safety';if(/incident|event|agency|case/.test(t))return 'Incident/Event';if(/call(?:ed)?\s+off|call-out|sick|illness|coverage|short|staff/.test(t))return 'Staffing / Coverage';if(/camera|amag|badge|reader|equipment|radio|computer/.test(t))return 'Systems / Equipment';return raw.type||'General'}
function siImpactPriority(c,detail){const t=String(detail||'').toLowerCase();if(/security breach|injury|police|fire|weapon|fight|theft|unauthorized|no coverage|left open|active leak|water damage/.test(t))return 'High';if(/repeated|every|again|still|recurring|multiple|jockey pump|tamper/.test(t))return 'Medium';if(['Incident/Event'].includes(c))return 'High';if(['Alarm / Fire System','Facility / Safety','Systems / Equipment'].includes(c))return 'Medium';return 'Normal'}
function siStatusRank(st){return {'Needs Action':0,'Recurring':1,'New':2,'Watching':3,'Dormant':4,'Reference Only':5,'Ignored':6,'Resolved':7}[st]??8}
function siDaysSince(iso){if(!iso)return 999;return Math.floor((Date.now()-parseISO(iso).getTime())/86400000)}
function siComputedStatus(issue){const st=issue.status||'New';if(['Resolved','Ignored','Reference Only'].includes(st))return st;const d=siDaysSince(issue.lastSeen);if(d>=14)return 'Dormant';if(d>=7)return 'Dormant';return st}
function siRecommendedAction(issue){const d=siDaysSince(issue.lastSeen);if(['Resolved','Ignored','Reference Only'].includes(issue.status))return issue.recommendedAction||'No active action.';if(issue.priority==='High')return 'Review for action owner and corrective follow-up.';if(d>=14)return 'No repeat mention in 14+ days. Suggest resolving if field conditions support it.';if(d>=7)return 'No repeat mention in 7+ days. Keep dormant/watch status unless it appears again.';if((issue.timesMentioned||1)>=3)return 'Recurring pattern. Review root cause and assign owner if needed.';return issue.recommendedAction||'Watch for repeat mention before escalating.'}
function siScoreMatch(item,issue){let score=0;const a=siWords(item.detail+' '+item.title),b=new Set(siWords(issue.title+' '+issue.managerNotes+' '+issue.recommendedAction));const overlap=a.filter(w=>b.has(w)).length;const loc1=item.location||siLocation(item.detail),loc2=issue.location||siLocation(issue.title+' '+issue.managerNotes);if(item.category===issue.category)score+=.35;if(loc1&&loc2&&loc1===loc2)score+=.25;score+=Math.min(.35,overlap*.06);if(String(item.title||'').toLowerCase()===String(issue.title||'').toLowerCase())score+=.15;return Math.min(1,score)}
function siCandidateFromRaw(raw,source='Shift Reports'){const detail=cleanShiftReportDetail(raw.detail||raw.message||raw.overview||raw.passdown||raw.title||'');const category=siCategory(raw);const location=raw.location||siLocation(detail+' '+(raw.title||''));const explicitRef=!!raw.referenceOnly||raw.priority==='Reference'||raw.defaultStatus==='No Action';const attendanceRef=category==='Staffing / Coverage'&&!/no coverage|coverage issue|short|left open|operational|post uncovered|missed/i.test(detail);const ref=explicitRef||siNoise(detail)||attendanceRef||/nothing else of note|no issues|n\/a|\bna\b/i.test(detail);const title=raw.title||(`${category}: ${detail.slice(0,48)}`);const recommended=raw.recommendedAction||(ref?'Store as reference only. Do not track unless it creates an operational issue.':'Review for operational impact and decide link/create/ignore.');return{title,category,detail,location,reportId:raw.reportId||'',date:raw.date||'',shift:raw.shift||'',source,priority:ref?'Reference':(raw.priority||siImpactPriority(category,detail)),referenceOnly:ref,suggestedLink:!!raw.suggestedLink,operationalClass:raw.operationalClass||shiftOperationalClass(raw),evidence:raw.evidence||'',recommendedAction:recommended}}
function siClassifyItem(item){if(item.referenceOnly)return{bucket:'Ignored / Reference',confidence:0,matchIssueId:'',suggestedMatches:[]};const active=(shiftIntel.issues||[]).filter(i=>!['Resolved','Ignored','Reference Only'].includes(i.status||'New'));const scored=active.map(i=>({id:i.id,title:i.title,category:i.category,score:siScoreMatch(item,i),status:i.status,lastSeen:i.lastSeen,timesMentioned:i.timesMentioned||1})).sort((a,b)=>b.score-a.score);const top=scored[0];if(top&&top.score>=.78)return{bucket:'Auto-Link',confidence:top.score,matchIssueId:top.id,suggestedMatches:scored.slice(0,3)};if(top&&top.score>=.42)return{bucket:'Suggested Matches',confidence:top.score,matchIssueId:'',suggestedMatches:scored.slice(0,3)};return{bucket:'New',confidence:0,matchIssueId:'',suggestedMatches:scored.slice(0,3)}}
function siAddIntake(raw,source){normalizeShiftIntel();const c=siCandidateFromRaw(raw,source);const cls=siClassifyItem(c);const key=[c.reportId,c.date,c.shift,c.category,c.title,c.detail.slice(0,120)].join('|').toLowerCase();if((shiftIntel.intake||[]).some(i=>i.dedupeKey===key))return false;shiftIntel.intake.unshift({id:shiftIntel.nextIntakeId++,dedupeKey:key,status:'Pending',createdAt:new Date().toISOString(),...c,...cls});return true}
async function generateShiftIntelIntake(){normalizeShiftReports();normalizeShiftIntel();let added=0;const eligible=(shiftReports.issues||[]).filter(i=>(i.status||'Open')!=='Closed');for(const i of eligible)if(siAddIntake(i,'Shift Reports'))added++;shiftIntelAudit('Generated intake from Shift Reports',`${added} intake item(s) added from ${eligible.length} eligible shift report item(s).`);if(!shiftIntelSelectedIntakeId){const first=pendingShiftIntelItems()[0];if(first)shiftIntelSelectedIntakeId=String(first.id);}shiftIntelDetailMode='intake';await saveShiftIntelNow('generate-intake');safeRenderPages();toast(`Shift Intelligence intake generated: ${added} new item(s)`)}
async function importShiftIntelReportFile(input){const files=Array.from(input&&input.files||[]);if(!files.length)return;let added=0;for(const f of files){const txt=await readShiftReportFile(f);const parsed=parseShiftReportText(txt,f.name);for(const raw of detectShiftReportIssues(parsed))if(siAddIntake({...raw,reportId:parsed.reportId,date:parsed.date,shift:parsed.shift},'Direct Import'))added++;}shiftIntelAudit('Direct report import',`${added} intake item(s) added from ${files.length} file(s).`);await saveShiftIntelNow('direct-import');safeRenderPages();if(input)input.value='';toast(`Shift Intelligence import complete: ${added} item(s)`)}
function siBucketCounts(){const pending=(shiftIntel.intake||[]).filter(i=>(i.status||'Pending')==='Pending');return{auto:pending.filter(i=>i.bucket==='Auto-Link').length,suggest:pending.filter(i=>i.bucket==='Suggested Matches').length,new:pending.filter(i=>i.bucket==='New').length,ref:pending.filter(i=>i.bucket==='Ignored / Reference').length,pending:pending.length}}
function siIssueMetrics(){const active=(shiftIntel.issues||[]).filter(i=>!['Resolved','Ignored','Reference Only'].includes(i.status||'New'));return{active:active.length,needs:active.filter(i=>i.status==='Needs Action').length,recurring:active.filter(i=>i.status==='Recurring').length,dormant:active.filter(i=>siComputedStatus(i)==='Dormant').length,resolved:(shiftIntel.issues||[]).filter(i=>i.status==='Resolved').length}}
function filteredShiftIntelIntake(){let q=String(shiftIntelSearch||'').toLowerCase().trim();return (shiftIntel.intake||[]).filter(i=>{if((i.status||'Pending')!=='Pending')return false;if(shiftIntelBucketFilter!=='all'&&i.bucket!==shiftIntelBucketFilter)return false;if(shiftIntelCategoryFilter!=='all'&&i.category!==shiftIntelCategoryFilter)return false;if(q&&!(`${i.title} ${i.detail} ${i.category} ${i.reportId} ${i.shift}`.toLowerCase().includes(q)))return false;return true;}).sort((a,b)=>['Auto-Link','Suggested Matches','New','Ignored / Reference'].indexOf(a.bucket)-['Auto-Link','Suggested Matches','New','Ignored / Reference'].indexOf(b.bucket)||String(b.date||'').localeCompare(String(a.date||'')))}
function filteredShiftIntelIssues(){let q=String(shiftIntelSearch||'').toLowerCase().trim();return (shiftIntel.issues||[]).filter(i=>{const comp=siComputedStatus(i);if(shiftIntelStatusFilter==='active'&&['Resolved','Ignored','Reference Only'].includes(i.status||'New'))return false;if(shiftIntelStatusFilter!=='active'&&shiftIntelStatusFilter!=='all'&&comp!==shiftIntelStatusFilter&&i.status!==shiftIntelStatusFilter)return false;if(shiftIntelCategoryFilter!=='all'&&i.category!==shiftIntelCategoryFilter)return false;if(q&&!(`${i.title} ${i.category} ${i.owner} ${i.managerNotes} ${i.resolutionNotes} ${i.recommendedAction}`.toLowerCase().includes(q)))return false;return true;}).sort((a,b)=>siStatusRank(siComputedStatus(a))-siStatusRank(siComputedStatus(b))||((b.priority==='High')-(a.priority==='High'))||String(b.lastSeen||'').localeCompare(String(a.lastSeen||'')))}
function pendingShiftIntelItems(){return (shiftIntel.intake||[]).filter(i=>(i.status||'Pending')==='Pending');}
function ensureShiftIntelSelection(intake,issues){
  if(shiftIntelDetailMode==='intake'){
    if(!intake.some(i=>String(i.id)===String(shiftIntelSelectedIntakeId)))shiftIntelSelectedIntakeId=intake[0]?String(intake[0].id):'';
    if(!shiftIntelSelectedIntakeId&&issues[0]){shiftIntelDetailMode='issue';shiftIntelSelectedIssueId=String(issues[0].id);}
  }else{
    if(!issues.some(i=>String(i.id)===String(shiftIntelSelectedIssueId)))shiftIntelSelectedIssueId=issues[0]?String(issues[0].id):'';
    if(!shiftIntelSelectedIssueId&&intake[0]){shiftIntelDetailMode='intake';shiftIntelSelectedIntakeId=String(intake[0].id);}
  }
}
function selectShiftIntelIntake(id){shiftIntelDetailMode='intake';shiftIntelSelectedIntakeId=String(id);safeRenderPages({preserveScroll:true});}
function selectShiftIntelIssue(id){shiftIntelDetailMode='issue';shiftIntelSelectedIssueId=String(id);safeRenderPages({preserveScroll:true});}
function selectNextShiftIntelIntake(){const next=pendingShiftIntelItems()[0];if(next){shiftIntelDetailMode='intake';shiftIntelSelectedIntakeId=String(next.id);}else{shiftIntelSelectedIntakeId='';}}
function renderShiftIntelQueueRow(i){const selected=shiftIntelDetailMode==='intake'&&String(i.id)===String(shiftIntelSelectedIntakeId);const cls=i.bucket==='Auto-Link'?'ok':i.bucket==='Suggested Matches'?'warn':i.bucket==='Ignored / Reference'?'':'critical';return `<button class="intel-queue-row ${selected?'selected':''}" onclick="selectShiftIntelIntake(${Number(i.id)})"><div class="intel-row-top"><div class="intel-row-title">${esc(i.title)}</div><span class="chip ${cls}">${esc(i.bucket)}</span></div><div class="intel-row-meta">${esc(i.category)} · ${esc(i.date||'')} · ${esc(i.shift||'')}<br>${esc(i.reportId||'')}</div>${i.evidence?`<div class="intel-row-signal"><span class="chip">${esc(i.evidence)}</span></div>`:''}</button>`;}
function renderShiftIntelWatchRow(i){const comp=siComputedStatus(i),selected=shiftIntelDetailMode==='issue'&&String(i.id)===String(shiftIntelSelectedIssueId);return `<button class="intel-watch-row ${selected?'selected':''}" onclick="selectShiftIntelIssue(${Number(i.id)})"><div class="intel-row-top"><div class="intel-row-title">SI-${String(i.id).padStart(4,'0')} · ${esc(i.title)}</div><span class="chip ${comp==='Needs Action'?'critical':comp==='Recurring'?'warn':''}">${esc(comp)}</span></div><div class="intel-row-meta">${esc(i.category)} · Priority ${esc(i.priority||'Normal')} · Last ${esc(i.lastSeen||'')}<br>${esc(i.owner||'No owner')} · ${Number(i.timesMentioned||1)} mention(s)</div></button>`;}
function renderShiftIntelMatches(item){const ms=item.suggestedMatches||[];if(!ms.length)return '<div class="mini-note">No existing watchlist issue meets the current matching threshold.</div>';return `<div class="intel-match-list">${ms.slice(0,4).map(m=>`<div class="intel-match-card"><div><strong>SI-${String(m.id).padStart(4,'0')} · ${esc(m.title)}</strong><span>${esc(m.status||'')} · ${Math.round(Number(m.score||0)*100)}% match</span></div><button class="sm" onclick="linkShiftIntelItem(${Number(item.id)},${Number(m.id)})">Link</button></div>`).join('')}</div>`;}
function renderShiftIntelIntakeDetail(item){
  if(!item)return `<div class="intel-detail-empty"><div><strong>No intake item selected</strong><br>Select an item from the review queue.</div></div>`;
  const primary=item.bucket==='Auto-Link'&&item.matchIssueId?`<button class="primary" onclick="linkShiftIntelItem(${Number(item.id)},${Number(item.matchIssueId)})">Approve Recommended Link</button>`:item.referenceOnly||item.bucket==='Ignored / Reference'?`<button class="primary" onclick="markShiftIntelReference(${Number(item.id)})">Store as Reference Only</button>`:`<button class="primary" onclick="approveShiftIntelNewIssue(${Number(item.id)})">Track as New Issue</button>`;
  return `<div class="intel-detail"><div class="intel-detail-kicker">Pending Decision · ${esc(item.bucket)}</div><div class="intel-detail-title">${esc(item.title)}</div><div class="intel-detail-meta"><span class="chip">${esc(item.category)}</span><span class="chip">${esc(item.reportId||'No report ID')}</span><span class="chip">${esc(item.date||'')}</span><span class="chip">${esc(item.shift||'')}</span>${item.location?`<span class="chip">${esc(item.location)}</span>`:''}</div><div class="intel-detail-section"><h4>Why it matters</h4><div class="intel-detail-copy">${esc(item.detail||'')}</div>${item.evidence?`<div class="mini-note"><strong>Evidence:</strong> ${esc(item.evidence)}</div>`:''}</div><div class="intel-detail-section"><h4>Recommended handling</h4><div class="intel-detail-copy">${esc(item.recommendedAction||'Review the operational impact and make a disposition.')}</div></div><div class="intel-detail-section"><h4>Suggested links</h4>${renderShiftIntelMatches(item)}</div><div class="intel-decision-bar"><strong>Disposition required</strong><div class="intel-decision-primary">${primary}</div><div class="intel-secondary-actions"><button onclick="openShiftIntelLinkModal(${Number(item.id)})">Choose Different Link</button>${!(item.referenceOnly||item.bucket==='Ignored / Reference')?`<button onclick="markShiftIntelReference(${Number(item.id)})">Reference Only</button>`:`<button onclick="approveShiftIntelNewIssue(${Number(item.id)},true)">Track Anyway</button>`}<button class="danger" onclick="ignoreShiftIntelItem(${Number(item.id)})">Ignore</button></div></div></div>`;
}
function renderShiftIntelIssueDetail(issue){
  if(!issue)return `<div class="intel-detail-empty"><div><strong>No watchlist issue selected</strong><br>Select an issue from the active watchlist.</div></div>`;
  const comp=siComputedStatus(issue);
  return `<div class="intel-detail"><div class="intel-detail-kicker">Active Watchlist · ${esc(comp)}</div><div class="intel-detail-title">SI-${String(issue.id).padStart(4,'0')} · ${esc(issue.title)}</div><div class="intel-detail-meta"><span class="chip">${esc(issue.category)}</span><span class="chip ${issue.priority==='High'?'critical':issue.priority==='Medium'?'warn':''}">Priority ${esc(issue.priority||'Normal')}</span><span class="chip">${Number(issue.timesMentioned||1)} mention(s)</span><span class="chip">Owner: ${esc(issue.owner||'Unassigned')}</span></div><div class="intel-detail-section"><h4>Operational posture</h4><div class="intel-detail-copy">${esc(siRecommendedAction(issue))}</div></div><div class="intel-detail-section"><h4>Report history</h4><div class="intel-detail-copy">First seen ${esc(issue.firstSeen||'Unknown')} · Last seen ${esc(issue.lastSeen||'Unknown')}<br>Shifts: ${esc((issue.shiftsReporting||[]).join(', ')||'Not listed')}<br>Linked dates: ${esc((issue.linkedReportDates||[]).join(', ')||'None')}</div></div>${issue.managerNotes?`<div class="intel-detail-section"><h4>Manager notes</h4><div class="intel-detail-copy">${esc(issue.managerNotes)}</div></div>`:''}<div class="intel-decision-bar"><strong>Watchlist action</strong><div class="intel-decision-primary"><button class="primary" onclick="openShiftIntelIssueNotes(${Number(issue.id)})">Assign / Update Notes</button><button class="gold" onclick="createTaskFromShiftIntelIssue(${Number(issue.id)})">Create Follow-Up Task</button></div><div class="intel-secondary-actions"><button onclick="updateShiftIntelIssueStatus(${Number(issue.id)},'Needs Action')">Needs Action</button><button onclick="updateShiftIntelIssueStatus(${Number(issue.id)},'Watching')">Watching</button><button onclick="updateShiftIntelIssueStatus(${Number(issue.id)},'Recurring')">Recurring</button><button onclick="updateShiftIntelIssueStatus(${Number(issue.id)},'Resolved')">Resolve</button><button onclick="updateShiftIntelIssueStatus(${Number(issue.id)},'Reference Only')">Reference Only</button></div></div></div>`;
}
function renderShiftIntelDetail(){if(shiftIntelDetailMode==='issue')return renderShiftIntelIssueDetail((shiftIntel.issues||[]).find(i=>String(i.id)===String(shiftIntelSelectedIssueId)));return renderShiftIntelIntakeDetail((shiftIntel.intake||[]).find(i=>String(i.id)===String(shiftIntelSelectedIntakeId)));}

function renderShiftIntelligence(){
  normalizeShiftIntel();
  const bc=siBucketCounts(),im=siIssueMetrics();
  const cats=[...new Set(['Alarm / Fire System','Logistics / Trailer Monitoring','Facility / Safety','Staffing / Coverage','Patrol / Safety','Incident/Event','Off-Duty Officer','Systems / Equipment','General'].concat((shiftIntel.issues||[]).map(i=>i.category),(shiftIntel.intake||[]).map(i=>i.category)).filter(Boolean))];
  const intake=filteredShiftIntelIntake();
  const issues=filteredShiftIntelIssues();
  ensureShiftIntelSelection(intake,issues);
  const actions=`<button class="primary" onclick="generateShiftIntelIntake()">Pull Intake</button><button onclick="document.getElementById('shiftIntelImportFile').click()">Import Direct</button><button onclick="exportShiftIntelCSV()">Export</button><button onclick="createShiftIntelBackup()">Backup</button>`;
  return `${shiftOpsHeader('Shift Operations · Decision Center','Shift Intelligence','Clear the intake queue through one deliberate decision, then manage only the issues that belong on the active watchlist.',actions)}
  ${renderShiftOpsPath(bc.pending?'review':'track')}
  <input id="shiftIntelImportFile" class="hidden" type="file" accept=".pdf,.txt,text/plain,application/pdf" multiple onchange="importShiftIntelReportFile(this)">
  <div class="intel-workspace">
    <section class="intel-pane focus"><div class="intel-pane-head"><div><h3>Intake Queue</h3><p>Select one signal. Every item must become Track, Link, Reference, or Ignore.</p></div><span class="chip warn">${intake.length}</span></div><div class="intel-pane-body"><div class="intel-queue-list">${intake.length?intake.map(renderShiftIntelQueueRow).join(''):'<div class="empty-state"><strong>Queue clear</strong><span>Pull intake from Shift Reports when a new report is ready.</span></div>'}</div><details class="intel-filter-drawer"><summary>Queue filters</summary><div class="intel-filter-grid"><div><label>Search</label><input value="${esc(shiftIntelSearch)}" oninput="shiftIntelSearch=this.value;safeRenderPages()" placeholder="Alarm, location, report..."></div><div><label>Intake bucket</label><select onchange="shiftIntelBucketFilter=this.value;safeRenderPages()"><option value="all">All Buckets</option>${['Auto-Link','Suggested Matches','New','Ignored / Reference'].map(x=>`<option ${shiftIntelBucketFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div><label>Category</label><select onchange="shiftIntelCategoryFilter=this.value;safeRenderPages()"><option value="all">All Categories</option>${cats.map(x=>`<option ${shiftIntelCategoryFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div></details></div></section>
    <section class="intel-pane"><div class="intel-pane-head"><div><h3>Decision Detail</h3><p>Why it matters, source evidence, suggested links, and the required disposition.</p></div><span class="chip">${shiftIntelDetailMode==='issue'?'Watchlist':'Intake'}</span></div>${renderShiftIntelDetail()}</section>
    <section class="intel-pane watch"><div class="intel-pane-head"><div><h3>Active Watchlist</h3><p>Needs Action and Recurring first. Select an issue to manage ownership, tasks, or closure.</p></div><span class="chip">${issues.length}</span></div><div class="intel-pane-body"><div class="intel-watch-list">${issues.length?issues.map(renderShiftIntelWatchRow).join(''):'<div class="empty-state"><strong>No active issues</strong><span>The watchlist is clean for the current filter.</span></div>'}</div><details class="intel-filter-drawer"><summary>Watchlist filter</summary><div class="intel-filter-grid"><div><label>Status</label><select onchange="shiftIntelStatusFilter=this.value;safeRenderPages()"><option value="active">Active</option>${['Needs Action','Recurring','New','Watching','Dormant','Resolved','Ignored','Reference Only','all'].map(x=>`<option ${shiftIntelStatusFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div></details></div></section>
  </div><details class="shift-rail-card danger-zone admin-only" style="margin-top:12px"><summary><strong>Administrative controls</strong></summary><div class="shift-rail-copy">Backup-first fresh start for Shift Reports and Shift Intelligence only.</div><button class="danger" style="margin-top:10px" onclick="openShiftMemoryClearModal()">Clear Shift Report Memory</button></details>`;
}
function renderShiftIntelIntakeItem(i){const cls=i.bucket==='Auto-Link'?'auto':i.bucket==='Suggested Matches'?'suggest':i.bucket==='New'?'new':'ref';return `<div class="si-item ${cls}"><div class="si-head"><div><div class="si-title">${esc(i.title)}</div><div class="si-meta">${esc(i.bucket)} · ${esc(i.category)} · ${esc(i.date||'')} · ${esc(i.shift||'')} · ${esc(i.reportId||'')}</div></div><span class="si-chip">${Math.round(Number(i.confidence||0)*100)}%</span></div><div>${esc(i.detail)}</div>${i.evidence?`<div class="mini-note"><strong>Evidence:</strong> ${esc(i.evidence)}</div>`:''}<div class="si-rec"><strong>Recommended:</strong> ${esc(i.recommendedAction||'Review item.')}</div>${renderShiftIntelSuggestedMatches(i)}<div class="si-actions">${i.bucket==='Auto-Link'&&i.matchIssueId?`<button class="sm primary" onclick="linkShiftIntelItem(${Number(i.id)},${Number(i.matchIssueId)})">Approve Auto-Link</button>`:''}<button class="sm gold" onclick="approveShiftIntelNewIssue(${Number(i.id)})">Create Issue</button><button class="sm" onclick="openShiftIntelLinkModal(${Number(i.id)})">Link / Suggested</button><button class="sm" onclick="markShiftIntelReference(${Number(i.id)})">Reference Only</button><button class="sm danger" onclick="ignoreShiftIntelItem(${Number(i.id)})">Ignore</button></div></div>`}
function renderShiftIntelSuggestedMatches(i){const ms=i.suggestedMatches||[];if(!ms.length)return '';return `<div>${ms.slice(0,3).map(m=>`<div class="si-match-row"><span>${esc(m.title)} <span class="muted">${esc(m.status||'')}</span></span><button class="sm" onclick="linkShiftIntelItem(${Number(i.id)},${Number(m.id)})">Link ${Math.round(Number(m.score||0)*100)}%</button></div>`).join('')}</div>`}
function renderShiftIntelIssue(i){const comp=siComputedStatus(i),cls=comp==='Needs Action'?'needs':comp==='Recurring'?'recurring':comp==='Dormant'?'dormant':'';return `<div class="si-issue ${cls}"><div class="si-head"><div><div class="si-title">SI-${String(i.id).padStart(4,'0')} · ${esc(i.title)}</div><div class="si-meta">${esc(comp)} · ${esc(i.category)} · Priority ${esc(i.priority)} · First ${esc(i.firstSeen||'')} · Last ${esc(i.lastSeen||'')} · ${Number(i.timesMentioned||1)} mention(s)</div></div><span class="si-chip">${esc(i.owner||'No owner')}</span></div><div class="shift-report-pills"><span class="si-chip">${esc((i.shiftsReporting||[]).join(', ')||'No shift')}</span><span class="si-chip">${esc((i.linkedReportDates||[]).slice(-5).join(', '))}</span></div><div class="si-rec"><strong>Recommended:</strong> ${esc(siRecommendedAction(i))}</div>${i.managerNotes?`<div class="notice"><strong>Manager Notes:</strong> ${esc(i.managerNotes)}</div>`:''}<div class="si-actions">${['Watching','Recurring','Needs Action','Resolved','Ignored','Reference Only'].map(st=>`<button class="sm" onclick="updateShiftIntelIssueStatus(${Number(i.id)},'${st}')">${esc(st)}</button>`).join('')}<button class="sm gold" onclick="openShiftIntelIssueNotes(${Number(i.id)})">Notes</button><button class="sm primary" onclick="createTaskFromShiftIntelIssue(${Number(i.id)})">Create Task</button></div></div>`}
function siLinkApply(item,issue){issue.lastSeen=item.date||issue.lastSeen||'';issue.timesMentioned=Number(issue.timesMentioned||1)+1;issue.shiftsReporting=[...new Set([...(issue.shiftsReporting||[]),item.shift].filter(Boolean))];issue.linkedReportDates=[...new Set([...(issue.linkedReportDates||[]),item.date].filter(Boolean))].sort();if(issue.status==='New'&&issue.timesMentioned>=2)issue.status='Watching';if(issue.timesMentioned>=3&&!['Needs Action','Resolved','Ignored','Reference Only'].includes(issue.status))issue.status='Recurring';if(item.priority==='High')issue.priority='High';issue.recommendedAction=siRecommendedAction(issue);}
async function linkShiftIntelItem(itemId,issueId){const item=shiftIntel.intake.find(i=>Number(i.id)===Number(itemId)),issue=shiftIntel.issues.find(i=>Number(i.id)===Number(issueId));if(!item||!issue){toast('Intake item or issue not found');return;}siLinkApply(item,issue);item.status='Linked';item.linkedIssueId=issue.id;shiftIntelDetailMode='issue';shiftIntelSelectedIssueId=String(issue.id);shiftIntelSelectedIntakeId='';shiftIntelAudit('Linked intake item',`${item.title} -> SI-${String(issue.id).padStart(4,'0')}`);await saveShiftIntelNow('link-item');safeRenderPages({preserveScroll:true});}
async function approveShiftIntelNewIssue(itemId,forceTrack=false){const item=shiftIntel.intake.find(i=>Number(i.id)===Number(itemId));if(!item)return;const issue={id:shiftIntel.nextIssueId++,title:item.title,category:item.category,status:item.referenceOnly&&!forceTrack?'Reference Only':'New',priority:forceTrack&&item.priority==='Reference'?'Normal':(item.priority||'Normal'),firstSeen:item.date||'',lastSeen:item.date||'',timesMentioned:1,shiftsReporting:[item.shift].filter(Boolean),linkedReportDates:[item.date].filter(Boolean),location:item.location||'',recommendedAction:item.recommendedAction||'',owner:'',managerNotes:'',resolutionNotes:''};shiftIntel.issues.unshift(issue);item.status='Created';item.linkedIssueId=issue.id;shiftIntelDetailMode='issue';shiftIntelSelectedIssueId=String(issue.id);shiftIntelSelectedIntakeId='';shiftIntelAudit('Created Shift Intelligence issue',`SI-${String(issue.id).padStart(4,'0')} · ${issue.title}${forceTrack?' · forced active track':''}`);await saveShiftIntelNow('create-issue');safeRenderPages({preserveScroll:true});}
function openShiftIntelLinkModal(itemId){const item=shiftIntel.intake.find(i=>Number(i.id)===Number(itemId));if(!item)return;const issues=filteredShiftIntelIssues().slice(0,30);showModal(`<div class="modal-title">Link Intake Item</div><div class="notice">${esc(item.title)}<br>${esc(item.detail)}</div><div class="table-wrap"><table><thead><tr><th>Issue</th><th>Status</th><th>Last Seen</th><th>Action</th></tr></thead><tbody>${issues.map(i=>`<tr><td>SI-${String(i.id).padStart(4,'0')} · ${esc(i.title)}</td><td>${esc(siComputedStatus(i))}</td><td>${esc(i.lastSeen||'')}</td><td><button onclick="linkShiftIntelItem(${Number(item.id)},${Number(i.id)});closeModal()">Link</button></td></tr>`).join('')||'<tr><td colspan="4">No active issues available.</td></tr>'}</tbody></table></div><div class="form-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="approveShiftIntelNewIssue(${Number(item.id)});closeModal()">Create New</button></div>`)}
async function markShiftIntelReference(itemId){const item=shiftIntel.intake.find(i=>Number(i.id)===Number(itemId));if(!item)return;item.status='Reference Only';shiftIntel.reference.unshift({...item,storedAt:new Date().toISOString()});shiftIntelSelectedIntakeId='';selectNextShiftIntelIntake();shiftIntelAudit('Stored reference item',item.title);await saveShiftIntelNow('reference-item');safeRenderPages({preserveScroll:true});}
async function ignoreShiftIntelItem(itemId){const item=shiftIntel.intake.find(i=>Number(i.id)===Number(itemId));if(!item)return;item.status='Ignored';shiftIntelSelectedIntakeId='';selectNextShiftIntelIntake();shiftIntelAudit('Ignored intake item',item.title);await saveShiftIntelNow('ignore-item');safeRenderPages({preserveScroll:true});}
async function updateShiftIntelIssueStatus(id,status){const issue=shiftIntel.issues.find(i=>Number(i.id)===Number(id));if(!issue)return;let note='';if(['Resolved','Ignored','Reference Only'].includes(status)){note=prompt(status+' note:')||'';if(!note.trim()){toast('A note is required.');return;}if(status==='Resolved')issue.resolutionNotes=(issue.resolutionNotes?issue.resolutionNotes+'\n':'')+note;else issue.managerNotes=(issue.managerNotes?issue.managerNotes+'\n':'')+status+': '+note;}issue.status=status;issue.recommendedAction=siRecommendedAction(issue);shiftIntelAudit('Updated Shift Intelligence status',`SI-${String(issue.id).padStart(4,'0')} · ${status}`);await saveShiftIntelNow('status-update');safeRenderPages({preserveScroll:true});}
function openShiftIntelIssueNotes(id){const issue=shiftIntel.issues.find(i=>Number(i.id)===Number(id));if(!issue)return;showModal(`<div class="modal-title">Shift Intelligence Notes</div><div class="form-grid"><div><label>Owner</label><input id="siOwner" value="${escAttr(issue.owner||'')}"></div><div><label>Priority</label><select id="siPriority">${['High','Medium','Normal','Low','Reference'].map(x=>`<option ${issue.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="span-2"><label>Manager Notes</label><textarea id="siMgr">${esc(issue.managerNotes||'')}</textarea></div><div class="span-2"><label>Resolution Notes</label><textarea id="siRes">${esc(issue.resolutionNotes||'')}</textarea></div></div><div class="form-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="saveShiftIntelIssueNotes(${Number(id)})">Save</button></div>`)}
async function saveShiftIntelIssueNotes(id){const issue=shiftIntel.issues.find(i=>Number(i.id)===Number(id));if(!issue)return;issue.owner=val('siOwner');issue.priority=val('siPriority')||issue.priority;issue.managerNotes=val('siMgr');issue.resolutionNotes=val('siRes');shiftIntelAudit('Updated Shift Intelligence notes',`SI-${String(issue.id).padStart(4,'0')}`);await saveShiftIntelNow('issue-notes');closeModal();safeRenderPages({preserveScroll:true});}
async function createShiftIntelBackup(){try{await SuiteBridge.send('suite:createBackup',shiftIntel,{module:'shift-intelligence'});toast('Shift Intelligence backup created')}catch(e){toast('Shift Intelligence backup failed: '+e.message)}}
function exportShiftIntelCSV(){const rows=[['ID','Title','Category','Status','Priority','First Seen','Last Seen','Times Mentioned','Shifts Reporting','Linked Report Dates','Recommended Action','Owner','Manager Notes','Resolution Notes'],...(shiftIntel.issues||[]).map(i=>['SI-'+String(i.id).padStart(4,'0'),i.title,i.category,siComputedStatus(i),i.priority,i.firstSeen,i.lastSeen,i.timesMentioned,(i.shiftsReporting||[]).join('; '),(i.linkedReportDates||[]).join('; '),siRecommendedAction(i),i.owner||'',i.managerNotes||'',i.resolutionNotes||''])];downloadCSV('PWADC_Shift_Intelligence_'+new Date().toISOString().slice(0,10)+'.csv',rows)}
PWADCModuleRegistry.register('shift-operations');
